function createExperienceContent() {

  const insertZone = () => {
    const target = document.querySelector('#productFeature');

    if (!target) return;

    if (document.getElementById('mcp-pdp-toast')) return;

    const zone = document.createElement('div');
    zone.id = 'mcp-pdp-toast';
    zone.className = 'evergage-content-zone';
    zone.style.minHeight = '2px';

    target.parentNode.insertBefore(zone, target);

    console.log('[Evergage] PDP zone inserted');
  };

  // Try immediate insert
  insertZone();

  // Observe DOM for React re-renders
  const observer = new MutationObserver(() => {
    insertZone();
  });

  observer.observe(document.body, {
    childList: true,
    subtree: true
  });

  // Stop observing after 5 seconds (performance safety)
  setTimeout(() => observer.disconnect(), 5000);
}

// ============================================================================
// SPA & NAVIGATION HELPERS
// ============================================================================

/**
 * Initializes default window.mcp object and intervals
 */
function createDefaults() {
  window.mcp = window.mcp || {};
  window.mcp.intervals = window.mcp.intervals || {};
}

/**
 * Clears all registered MCP intervals
 */
function clearIntervals() {
  for (let id in window.mcp.intervals) {
    clearInterval(window.mcp.intervals[id]);
  }
}

/**
 * Monitors URL changes and reinitializes MCP on navigation in SPA
 */
function watchURL() {
  let reference = window.location.href;
  window.mcp.intervals.spa = setInterval(() => {
    const skeleton = document.querySelector("#app-main > .chakra-skeleton");
    if (
      reference !== window.location.href &&
      document.readyState === "complete" &&
      !skeleton
    ) {
      reference = window.location.href;
      SalesforceInteractions.reinit();
    }
  }, 50);
}

/**
 * Builds array of parent nodes from event target up through DOM tree
 * @param {object} event - DOM event object
 * @param {number} iterations - Max iterations (default: 50)
 * @returns {array} Array of DOM nodes
 */
function eventPath(event, iterations = 50) {
  let path = [];
  let complete = true;
  let currentParentNode;
  let x = 1;

  if (event.target) {
    path.push(event.target);
    if (event.target.parentNode) {
      complete = false;
      currentParentNode = event.target.parentNode;
    }
    while (!complete) {
      x++;
      path.push(currentParentNode);
      if (currentParentNode && currentParentNode.parentNode) {
        currentParentNode = currentParentNode.parentNode;
      } else {
        complete = true;
      }
      if (x === iterations) {
        complete = true;
      }
    }
  }
  return path;
}

/**
 * Polls a condition and executes callback when met or timeout occurs
 * @param {function} successCallback - Executed when condition is met
 * @param {function|boolean} condition - Condition to check
 * @param {number} waitTime - Max wait time in ms (default: 2000)
 * @param {number} pollingTime - Polling interval in ms (default: 100)
 * @param {function} timeoutCallback - Executed on timeout
 * @returns {Promise} Resolves with callback result
 */
function wait(
  successCallback,
  condition,
  waitTime,
  pollingTime,
  timeoutCallback
) {
  return new Promise((resolve) => {
    const start = new Date();
    let interval = setInterval(function () {
      try {
        if (typeof condition === "function" ? condition() : condition) {
          clearInterval(interval);
          const response =
            typeof successCallback === "function"
              ? successCallback()
              : successCallback;
          resolve(response);
        } else if (new Date() - start > (waitTime || 2000)) {
          clearInterval(interval);
          const response =
            typeof timeoutCallback === "function"
              ? timeoutCallback()
              : timeoutCallback;
          resolve(response);
        }
      } catch (err) {
        clearInterval(interval);
        console.error("🔴 MCP: Error in wait function:", err);
      }
    }, pollingTime || 100);
  });
}

// ============================================================================
// UTM & TRACKING HELPERS
