/**
 * Captures UTM parameters and stores them in Profile Object for historical tracking
 * @param {object} event - MCP event object
 * @param {string} objectName - Name of the profile object (default: "UTMParameters")
 * @returns {object} Modified event object
 */
function buildUTMParametersPO(event, objectName = "UTMParameters") {
  try {
    const queryString = window.location.search;
    const params = new URLSearchParams(queryString);
    const source = params.get("utm_source");
    const term = params.get("utm_term");
    const campaign = params.get("utm_campaign");
    const medium = params.get("utm_medium");
    const content = params.get("utm_content");

    // Generate unique ID
    const id = randomId();

    if (source || term || campaign || medium || content) {
      event.user = event.user || {};
      event.user.profileObjects = event.user.profileObjects || {};
      event.user.profileObjects[objectName] = [
        {
          id: id,
          attributes: {
            source: source,
            term: term,
            campaign: campaign,
            medium: medium,
            content: content,
            date: new Date(),
          },
        },
      ];
    }
  } catch (err) {
    console.error("🔴 MCP: Error building UTM parameters PO:", err);
  }
  return event;
}

/**
 * Captures UTM parameters and writes latest values to user attributes
 * @param {object} event - MCP event object
 * @returns {object} Modified event object
 */
function buildUTMParametersAttributes(event) {
  try {
    const queryString = window.location.search;
    const params = new URLSearchParams(queryString);
    const source = params.get("utm_source") || " ";
    const term = params.get("utm_term") || " ";
    const campaign = params.get("utm_campaign") || " ";
    const medium = params.get("utm_medium") || " ";
    const content = params.get("utm_content") || " ";

    if (
      source !== " " ||
      term !== " " ||
      campaign !== " " ||
      medium !== " " ||
      content !== " "
    ) {
      event.user = event.user || {};
      event.user.attributes = event.user.attributes || {};
      event.user.attributes["utm_source"] = source;
      event.user.attributes["utm_term"] = term;
      event.user.attributes["utm_campaign"] = campaign;
      event.user.attributes["utm_medium"] = medium;
      event.user.attributes["utm_content"] = content;
      event.user.attributes["utm_date"] = new Date();
    }
  } catch (err) {
    console.error("🔴 MCP: Error building UTM attributes:", err);
  }
  return event;
}

// ============================================================================
// ADOBE XDM EVENT HANDLERS
// ============================================================================

/**
 * Captures and stores Adobe XDM events with deduplication
 * @param {object} event - Adobe Analytics event object
 */
function handleAdobeEvent(event) {
  try {
    const xdmData =
      event?.detail?.xdm || event?.detail?.data?.xdm || event?.detail || null;

    if (!xdmData) {
      console.log("🟡 MCP: Adobe event fired but no XDM data found", event);
      return;
    }
    window.mcp.xdmEvents = window.mcp.xdmEvents || [];

    // Deduplicate: check if this exact event already exists
    const isDuplicate = window.mcp.xdmEvents.some((existing) => {
      // Use eventMergeId if available, otherwise compare eventType + timestamp
      if (xdmData.eventMergeId) {
        return existing.eventMergeId === xdmData.eventMergeId;
      }
      // Fallback: compare type and ensure it's very recent (within 100ms)
      return (
        existing.eventType === xdmData.eventType &&
        Math.abs(new Date() - new Date(existing._timestamp || 0)) < 100
      );
    });

    if (isDuplicate) {
      return;
    }

    // Add timestamp for deduplication
    xdmData._timestamp = new Date();

    // Add to array
    window.mcp.xdmEvents.unshift(xdmData);

    // Keep only last 5
    if (window.mcp.xdmEvents.length > 5) {
      window.mcp.xdmEvents = window.mcp.xdmEvents.slice(0, 5);
    }

    window.mcp.lastXDM = xdmData;
    window.mcp.lastAdobeEvent = event;
  } catch (err) {
    console.error("🔴 MCP: handleAdobeEvent error:", err);
  }
}
/**
 * Generic helper to get XDM events by type and optional page type
 * @param {string} eventType - The XDM event type to search for
 * @param {string|null} pageType - Optional page type to filter by
 * @returns {object|null} The matching XDM event or null
 */
function getLastXDMByType(eventType, pageType = null) {
  if (!window.mcp.xdmEvents) return null;
  return window.mcp.xdmEvents.find((xdm) => {
    const matchesEvent = xdm.eventType === eventType;
    const matchesPage =
      !pageType || xdm._thegoodyeartirerubbercompany?.pageType === pageType;
    return matchesEvent && matchesPage;
  });
}
/**
 * Gets last page view XDM event
 * @returns {object|null} XDM event or null
 */
function getLastPageViewXDM() {
  return getLastXDMByType("web.webpagedetails.pageViews");
}

/**
 * Gets last product page view XDM event
 * @returns {object|null} XDM event or null
 */
function getLastProductViewXDM() {
  return getLastXDMByType("web.webpagedetails.pageViews", "Products");
}

/**
 * Gets last cart page view XDM event
 * @returns {object|null} XDM event or null
 */
function getLastCartViewXDM() {
  return getLastXDMByType("web.webpagedetails.pageViews", "cart");
}

