/**
 * Check if all required tire data is available
 * Checks if properties exist (loaded), not if they have values
 */
function hasRequiredTireData() {
  if (!window.xdmLayer) {
    // Fallback for Stage: DOM-based check
    return (
      (SalesforceInteractions.cashDom(
        '[data-qa-id="ProductDetails-info-section"]'
      ).length > 0 &&
      SalesforceInteractions.cashDom(
        '[data-qa-id="ProductDetails-product-price-1"]'
      ).length > 0) || 
      (SalesforceInteractions.cashDom(
        '[data-qa-id="unqualified-product-information-container"]'
      ).length > 0)

    );
  }

  // Check productListItems properties exist (even if empty)
  const productItem = window.xdmLayer.productListItems?.[0];
  const hasProductList =
    productItem &&
    typeof productItem.SKU !== "undefined" &&
    typeof productItem.name !== "undefined" &&
    typeof productItem._thegoodyeartirerubbercompany.listPrice !== "undefined";

  // Check serverProductData.getProduct.product properties exist (even if blank)
  //   const product = window.xdmLayer.serverProductData?.getProduct?.product;
const product = window.xdmLayer.serverProductData;


  if (!product) return false;

  // Check that properties are defined (loaded), not that they have values
  const hasServerData =
    typeof product.brand !== "undefined" &&
    typeof product.shortDescription !== "undefined" &&
    product.specification &&
    typeof product.specification.tireSizeCode !== "undefined" &&
    typeof product.width !== "undefined";

  return hasProductList && hasServerData;
}
/**
 * Extracts locale from URL path
 * @returns {string} Locale in format "en-US"
 */
function getLocale() {
  const path = window.location.pathname;
  const part = path.split("/")[1]; // locale in url = en_us
  if (part) {
    const [lang, region] = part.split("-");
    return `${lang.toLowerCase()}-${region.toUpperCase()}`;
  } else return "en-US";
}

/**
 * Extracts category from breadcrumb navigation or URL
 * @returns {string} Category name or path
 */
function getCategoryFromBreadcrumbs() {
  try {
    const crumbElements = SalesforceInteractions.cashDom(
      "nav[aria-label='Breadcrumb'] ol li a, nav[aria-label='Breadcrumb'] ol li span[aria-current='page']"
    );

    if (crumbElements && crumbElements.length > 0) {
      const crumbTexts = [];

      crumbElements.each((index, el) => {
        const text = SalesforceInteractions.cashDom(el)
          .text()
          .replace(/\u00A0/g, " ")
          .replace(/\s+/g, " ")
          .trim();

        if (text && text !== "/") {
          crumbTexts.push(text);
        }
      });

      if (crumbTexts.length > 0) {
        // Skip "Home" and join remaining breadcrumbs
        const filteredCrumbs = crumbTexts.filter(
          (crumb) => crumb.toLowerCase() !== "home"
        );
        return filteredCrumbs.length > 0
          ? filteredCrumbs.join(" | ")
          : "Unknown Category";
      }
    }

    // Fallback: extract from URL
    const pathname = window.location.pathname;
    const pathParts = pathname.split("/").filter(Boolean);

    if (pathParts.length > 0) {
      const lastSegment = pathParts[pathParts.length - 1];
      return lastSegment
        .split("-")
        .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
        .join(" ");
    }

    return "Unknown Category";
  } catch (err) {
    console.error("🔴 MCP: Error extracting category from breadcrumbs:", err);
    return "Unknown Category";
  }
}

/**
 * Helper function to determine product type from URL
 * @returns {'tire' | 'service' | 'unknown'}
 */
function getProductType() {
  const pathname = window.location.pathname;

  if (/\/services\//.test(pathname)) {
    return "service";
  }

  if (/\/tires\//.test(pathname)) {
    return "tire";
  }

  return "unknown";
}

function getTireTypeTags() {
  const tags = [];

  try {
    const tagElements = SalesforceInteractions.cashDom(
            'ul[data-qa-id="pdp-tags-tag-wrapper"] span[data-qa-id^="tag-label-"]'
    );
    
        // ).first();


    if (tagElements.length === 0) return [];

    tagElements.each((index, el) => {
      const text = SalesforceInteractions.cashDom(el).text().trim();

      // Filter out warranty tags, keep only tire type/season tags
      if (text && !/warranty|mi/i.test(text)) {
        tags.push(text);
      }
    });
  } catch (err) {
    console.error("Error getting tire type tags:", err);
  }

  return tags;
}
/**
 * Extracts specification value from product specification table
 * @param {string} specName - Name of the specification to find
 * @returns {string|null} Specification value or null
 */
function getSpecValue(specName) {
  try {
    const specElements = SalesforceInteractions.cashDom(
           'section#productSpecification th[aria-label="Specification Title"]'
    );

    for (let i = 0; i < specElements.length; i++) {
      const dt = specElements[i];
      const title = SalesforceInteractions.cashDom(dt).text().trim();

      if (title === specName) {
        // Get the next dd sibling
        const dd = SalesforceInteractions.cashDom(dt).next(
                    'td[aria-label="Specification Value"]'
        );
        if (dd.length > 0) {
          return dd.text().trim();
        }
      }
    }

    return null;
  } catch (err) {
    console.error(`🔴 MCP: Error extracting spec ${specName}:`, err);
    return null;
  }
}

/**
 * Parses product ID from URL query parameter
 * @param {string} href - Full URL or path with productId parameter
 * @returns {string|null} Product ID or null if not found
 */
function getProductIdFromHref(href) {
  try {
    const url = new URL(href);
    return url.searchParams.get("productId") || null;
  } catch (e) {
    console.error("🔴 MCP: Error extracting productId from href:", e);
    return null;
  }
}

/**
 * Extract product ID from URL path
 * Works for both tires and services
 * Examples:
 *   - /en_us/services/engine-diagnostic-service_155281 → 155281
 *   - /en_us/tires/assurance-weatherready-2_24987-76718067300000 → 24987-76718067300000
 * @returns {string|null} Product ID or null if not found
 */
function getProductIdFromPath() {
  try {
    const pathname = window.location.pathname;
    // Match everything after the last underscore until end or trailing slash
    // Captures digits and hyphens: _[ID]/? or _[ID]
    const match = pathname.match(/-([0-9-]+)\/?$/) || pathname.match(/_([0-9-]+)\/?$/);
    return match ? match[1] : null;
  } catch (err) {
    console.error("🔴 MCP: Error extracting productId from path:", err);
    return null;
  }
}

/**
 * Returns functions to extract service-specific data from DOM
 * @returns {object} Object with name(), description(), and category() extractors
 */
function getServiceData() {
  return {
    name: () => {
      const nameEl = SalesforceInteractions.cashDom(
        '[data-qa-id="ProductDetails-service-name-heading"]'
      );
      return nameEl.length > 0 ? nameEl.text().trim() : undefined;
    },

    description: () => {
      const descEl = SalesforceInteractions.cashDom(
        '[data-qa-id="ProductDetails-service-short-description"]'
      );
      return descEl.length > 0 ? descEl.text().trim() : undefined;
    },

    category: () => {
      const categoryEl = SalesforceInteractions.cashDom(
        '[data-qa-id="ProductDetails-service-brand"]'
      );
      return categoryEl.length > 0 ? categoryEl.text().trim() : [];
    },
  };
}

