/**
 * Extracts product ID from quickview modal details link
 * @returns {string|null} Product ID or null if not found
 */
function getProductIdFromQuickview() {
  try {
    // Try to get from URL parameter in the quickview links
    const detailsLink = SalesforceInteractions.cashDom(
      '[data-qa-id="ProductListing-tire-details-link"]'
    );
    if (detailsLink.length > 0) {
      const href = detailsLink.attr("href");
      return getProductIdFromHref(window.location.origin + href) || null;
    }
    return null;
  } catch (err) {
    console.error("🔴 MCP: Error extracting productId from quickview:", err);
    return null;
  }
}

/**
 * Helper function to get quantity from quickview modal input
 * @returns {number} The quantity value (defaults to 1 if not found)
 */
function getQuantityFromQuickview() {
  const quantityInput = SalesforceInteractions.cashDom(
    '[data-qa-id="ProductListing-regular-tires-input-field"]'
  );
  if (quantityInput.length > 0) {
    const qtyValue = quantityInput.val() || quantityInput.attr("value");
    return parseInt(qtyValue) || 1;
  }
  return 1;
}

/**
 * Extracts tire details from quickview modal (brand, name, price, quantity, installation fee)
 * @returns {object|null} Tire details object or null on error
 */
function getTireDetailsFromQuickview() {
  try {
    const details = {
      brand: null,
      name: null,
      price: null,
      quantity: 1,
      installationFee: 0,
    };

    // Get brand
    const brandEl = SalesforceInteractions.cashDom(
      '[data-qa-id="ProductListing-tire-details-brand"]'
    );
    if (brandEl.length > 0) {
      details.brand = brandEl.text().trim();
    }

    // Get product name
    const nameEl = SalesforceInteractions.cashDom(
      '[data-qa-id="ProductListing-tire-details-name"]'
    );
    if (nameEl.length > 0) {
      details.name = nameEl.text().trim();
    }

    // Get price (per tire)
    const priceEl = SalesforceInteractions.cashDom(
      '[data-qa-id="ProductListing-product-price-1"]'
    );
    if (priceEl.length > 0) {
      details.price = extractPrice(priceEl.text());
    }

    // Get quantity using helper function
    details.quantity = getQuantityFromQuickview();

    // Get installation fee (per tire)
    const installationRow = SalesforceInteractions.cashDom(
      '[data-qa-id^="row-price-accordion-quickview-price-1"]'
    );
    if (installationRow.length > 0) {
      details.installationFee = extractPrice(installationRow.text());
    }
    return details;
  } catch (err) {
    console.error("🔴 MCP: Error extracting tire details:", err);
    return null;
  }
}

/**
 * Extracts add-on service details from service container
 * @param {Object} serviceContainer - cashDom element of service container
 * @returns {Object|null} Object containing id, name, description, price
 */
function getAddOnServiceDetails(serviceContainer) {
  try {
    const cashDom = SalesforceInteractions.cashDom;

    // Extract service ID from data-testid attribute
    const containerTestId = serviceContainer.attr("data-testid");
    if (!containerTestId) {
      console.error("🔴 MCP: No data-testid found on service container");
      return null;
    }

    // Extract ID by removing '-container' suffix
    const serviceId = containerTestId.replace("-container", "");

    // Extract service name
    const name = serviceContainer
      .find("label.subtitle-lg")
      .first()
      .text()
      .trim();

    // Extract price
    const priceText = serviceContainer
      .find("label.subtitle-md.text-ui-accessible")
      .first()
      .text()
      .trim();
    const priceMatch = priceText.match(/\$?([\d,]+\.?\d*)/);
    const price = priceMatch
      ? parseFloat(priceMatch[1].replace(/,/g, ""))
      : null;

    if (!serviceId || !name || !price) {
      console.error("🔴 MCP: Missing required service data:", {
        serviceId,
        name,
        price,
      });
      return null;
    }
    return {
      id: serviceId,
      name: name,
      price: price,
    };
  } catch (err) {
    console.error("🔴 MCP: Error extracting add-on service details:", err);
    return null;
  }
}

