/**
 * Extract all line items from the cart page
 * Handles tires, add-on services, installation, and standalone services
 * @returns {Array} Array of line item objects with catalogObjectType, catalogObjectId, price, quantity
 */
function extractCartLineItems() {
  const lineItems = [];
  const cashDom = SalesforceInteractions.cashDom;

  // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  // TIRE PRODUCTS (with add-ons nested inside)
  // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  const tireImageLinks = cashDom(
    '[data-qa-id="CartContainer-cart-line-item-image-link"]'
  );

  tireImageLinks.each((index, link) => {
    try {
      const imageLink = cashDom(link);
      const href = imageLink.attr("href");
      if (!href) return;

      const productId = getProductIdFromHref(window.location.origin + href);
      if (!productId) return;

      const fieldset = imageLink.closest("fieldset");

      const quantityInput = fieldset.find(
        '[data-qa-id="CartContainer-cart-Container-cart-line-item-quantity-input-field"]'
      );
      const quantity = parseInt(quantityInput.val()) || 1;

      const perEaLabel = fieldset.find(
        '[data-qa-id="CartContainer-cart-Container-cart-line-item-tire-price"]'
      );
      const price = extractPrice(perEaLabel.text()) || 1;

      lineItems.push({
        catalogObjectType: "Product",
        catalogObjectId: productId,
        price: price,
        quantity: quantity,
      });

      // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
      // ADD-ON SERVICES (Road Hazard, Alignment, etc.)
      // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
      const removeButtons = fieldset.find(
        '[data-qa-id$="service-addon-remove-link"]'
      );

      removeButtons.each((idx, button) => {
        try {
          const trackingData = cashDom(button).attr("data-tracking");
          if (!trackingData) return;

          const tracking = JSON.parse(trackingData);

          lineItems.push({
            catalogObjectType: "Product",
            catalogObjectId: tracking.addonSKU,
            price: parseFloat(tracking.addonPrice) || 1,
            quantity: 1,
          });
        } catch (err) {
          console.error("🔴 MCP: Error parsing add-on tracking:", err);
        }
      });
    } catch (err) {
      console.error("🔴 MCP: Error extracting tire product:", err);
    }
  });

  // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  // STANDALONE SERVICES (Wiper Blade, Oil Change, etc.)
  // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  const serviceImageLinks = cashDom(
    '[data-qa-id="CartContainer-service-line-item-image-link"]'
  );

  serviceImageLinks.each((index, link) => {
    try {
      const href = cashDom(link).attr("href");
      if (!href) return;

      const serviceId = getProductIdFromHref(window.location.origin + href);
      if (!serviceId) return;

      lineItems.push({
        catalogObjectType: "Product",
        catalogObjectId: serviceId,
        price: 1,
        quantity: 1,
      });
    } catch (err) {
      console.error("🔴 MCP: Error extracting standalone service:", err);
    }
  });

  // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  // INSTALLATION (from Order Summary)
  // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  try {
    const installationValueEl = cashDom(
      '[data-qa-id="CartContainer-cart-order-summary-Installation-value"]'
    );

    if (installationValueEl.length > 0) {
      const installationPrice = extractPrice(installationValueEl.text().trim());

      if (installationPrice && installationPrice > 0) {
        lineItems.push({
          catalogObjectType: "Product",
          catalogObjectId: "Installation",
          price: installationPrice,
          quantity: 1,
        });
      }
    }
  } catch (err) {
    console.error("🔴 MCP: Error extracting installation:", err);
  }

//   console.log(`✅ MCP: Extracted ${lineItems.length} line items`);

  return lineItems;
}

