        //     //   window.location.pathname
        //     /^\/en_us\/(services\/product|tires)\/(?!.*_[A-Z]+-\d+)(?!.*_\d+)(?:[\w-]+\/?)+$/.test(
        //       window.location.pathname
        //     )
        //   ) {
        //     const onSuccess = () => {
        //       return true;
        //     };
        //     const condition = () => {
        //       const hasBreadcrumbs =
        //         SalesforceInteractions.cashDom(
        //           "nav[aria-label='Breadcrumb'] ol li"
        //         ).length > 0;
        //       const hasXDMData = getLastPageViewXDM() !== null;
        //       return hasBreadcrumbs && hasXDMData;
        //     };

        //     return wait(onSuccess, condition, 5000, 50, false);
        //   }

        //   return false;
            const pathname = window.location.pathname;
            const search = window.location.search;

            // 🚫 Exclude Query PDP
            if (
                (pathname === "/en-us/services/product" ||
                pathname === "/en-us/tires/product") &&
                search.includes("productId=")
            ) {
                return false;
            }

            // 🚫 Exclude Slug PDP
            if (
                /^\/en-us\/(tires|services)\/[\w-]+_[A-Z]+-\d+\/?$/.test(pathname) ||
                /^\/en-us\/(tires|services)\/[\w-]+_\d+(-\d+)?\/?$/.test(pathname)
            ) {
                return false;
            }

            // ✅ Allow Category pages only
            if (/^\/en-us\/tires(\/[\w-]+)*\/?$/.test(pathname) || /^\/en-us\/tires(\/[\w-]+)*\/?$/.test(pathname)) {
                return false;
            }

            const condition = () => {
                const hasBreadcrumbs =
                SalesforceInteractions.cashDom(
                    "nav[aria-label='Breadcrumb'] ol li"
                ).length > 0;

                const hasXDMData = getLastPageViewXDM() !== null;

                return hasBreadcrumbs && hasXDMData;
            };

